  `GetDsTime` timestamp NULL DEFAULT NULL COMMENT '上次设备状态信息查询应答时间',
  `HasAlarm` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否有报警',
  `CreateTime` timestamp NOT NULL DEFAULT '1999-12-31 16:00:00' COMMENT '创建时间',
  `UpTime` timestamp NOT NULL DEFAULT '1999-12-31 16:00:00' COMMENT '更新时间',
  `NickName` varchar(255) NOT NULL DEFAULT '' COMMENT '别名',
  `SubscribeExpires` int NOT NULL DEFAULT '0' COMMENT '目录订阅有效期',
  PRIMARY KEY (`DeviceID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
